SELECT DISTINCT 基金经理代码, 基金经理姓名, 在任基金数(只) 
FROM 公募基金衍生指标_基金经理收益与规模同类分析
LIMIT 20;

SELECT 基金经理代码, 基金经理姓名, "在任基金数(只)" 
FROM 公募基金衍生指标_基金经理收益与规模同类分析
LIMIT 20;

SELECT AVG(t."在任基金数(只)") as avg_funds_per_manager
FROM (
    SELECT DISTINCT 基金经理代码, "在任基金数(只)"
    FROM 公募基金衍生指标_基金经理收益与规模同类分析
) t;

SELECT ROUND(AVG(t."在任基金数(只)"), 2) as avg_funds_per_manager
FROM (
    SELECT 基金经理代码, "在任基金数(只)"
    FROM 公募基金衍生指标_基金经理收益与规模同类分析
    GROUP BY 基金经理代码
) t;

SELECT ROUND(AVG("在任基金数(只)"), 2) as avg_funds_per_manager
FROM (
    SELECT DISTINCT 基金经理代码, "在任基金数(只)"
    FROM 公募基金衍生指标_基金经理收益与规模同类分析
) t;

-- Check total unique fund codes vs manager codes
SELECT COUNT(DISTINCT 基金内部编码) as total_funds FROM 公募基金概况;
SELECT COUNT(DISTINCT 基金经理代码) as total_managers FROM 公募基金衍生指标_基金经理收益与规模同类分析;
